service.method:

DELETE FROM
	UPUSO
WHERE
	HOUSE_CODE 	= ${HOUSE_CODE}
AND CODE       	= ${CODE}
AND `TYPE`		= ${TYPE}
AND OPTION_NAME = ${OPTION_NAME}


INSERT INTO UPUSO
(
	  HOUSE_CODE
	, CODE
	, `TYPE`
	, OPTION_NAME
	, ADD_DATE
	, ADD_TIME
	, ADD_USER_ID
	, CHANGE_DATE
	, CHANGE_TIME
	, CHANGE_USER_ID
	, OPTION_VALUE
)
VALUES
(
	  ${HOUSE_CODE}
	, ${CODE}
	, ${TYPE}
	, ${OPTION_NAME}
	, ${current.DATE}
	, ${current.TIME}
	, ${session.ID}
	, ${current.DATE}
	, ${current.TIME}
	, ${session.ID}
	, ${OPTION_VALUE}
)


    	INSERT INTO UPUSO_HISTORY
		(
			  HISTORY_KEY
			, ACTION_MODE
			, HOUSE_CODE
			, CODE
			, `TYPE`
			, OPTION_NAME
			, OPTION_VALUE
			, ADD_USER_ID
			, ADD_DATE
			, ADD_TIME
		)
		VALUES
		(
			  ${HISTORY_KEY}
			, ${ACTION_MODE}
			, ${HOUSE_CODE}
			, ${CODE}
			, ${TYPE}
			, ${OPTION_NAME}
			, ${OPTION_VALUE}
			, ${session.ID}
			, ${current.DATE}
			, ${current.TIME}
		)
